from collections import deque
non={(r,c) for r in range(9,19) for c in range(20) if grid[r][c]!=1}
comps=[]
while non:
 p=non.pop(); q=[p]; cc={p}
 while q:
  r,c=q.pop()
  for x in [(r-1,c),(r+1,c),(r,c-1),(r,c+1)]:
   if x in non: non.remove(x); cc.add(x); q.append(x)
 comps.append(cc)
for comp in sorted(comps,key=lambda a:(min(r for r,c in a),min(c for r,c in a))):
 r0=min(r for r,c in comp); c0=min(c for r,c in comp)
 sh={(r-r0,c-c0):grid[r][c] for r,c in comp}
 h=max(r for r,c in sh)+1; w=max(c for r,c in sh)+1
 print('origin',r0,c0,'shape',h,w,'n',len(comp),'rows', [''.join(str(sh.get((i,j),'.')) for j in range(w)) for i in range(h)])

pieces=[]
for comp in comps:
 r0=min(r for r,c in comp); c0=min(c for r,c in comp)
 cells={(r-r0,c-c0):grid[r][c] for r,c in comp}
 pieces.append({'cells':cells,'src':(r0,c0)})
# enumerate placements for each individual tile
for i,p in enumerate(pieces):
 h=max(r for r,c in p['cells'])+1; w=max(c for r,c in p['cells'])+1
 pls=[]
 for r0 in range(8-h+1):
  for c0 in range(20-w+1):
   coords={(r0+r,c0+c) for r,c in p['cells']}
   if coords<=mask: pls.append((r0,c0,coords))
 p['placements']=pls
 print(i,p['src'],len(p['cells']),len(pls))

families=[]
for sig,inds in sigs.items():
 p=pieces[inds[0]]
 h=max(r for r,c in p['cells'])+1; w=max(c for r,c in p['cells'])+1
 pls=[]
 for r0 in range(8-h+1):
  for c0 in range(20-w+1):
   coords={(r0+r,c0+c) for r,c in p['cells']}
   if coords<=mask:
    cm=sum(1<<(r*20+c) for r,c in coords)
    vals=tuple((r0+r,c0+c,v) for (r,c),v in p['cells'].items())
    pls.append({'a':(r0,c0),'cm':cm,'coords':coords,'vals':vals})
 families.append({'sig':sig,'count':len(inds),'inds':inds,'pls':pls,'cells':p['cells']})
allmask=sum(1<<(r*20+c) for r,c in mask)
bycell={}
for r,c in mask:
 bycell[(r,c)]=[(fi,pl) for fi,f in enumerate(families) for pl in f['pls'] if pl['cm']>>(r*20+c)&1]
solutions=[]; nodes=0
remaining=[f['count'] for f in families]
def search(occ,chosen):
 global nodes
 nodes+=1
 if occ==allmask:
  if all(x==0 for x in remaining): solutions.append(chosen.copy())
  return len(solutions)>=30
 # choose open cell min candidates available and nonoverlap
 best=None; bestcand=None
 for r,c in mask:
  bit=1<<(r*20+c)
  if occ&bit: continue
  cand=[]
  for fi,pl in bycell[(r,c)]:
   if remaining[fi] and not (pl['cm']&occ): cand.append((fi,pl))
  if bestcand is None or len(cand)<len(bestcand):
   best=(r,c); bestcand=cand
   if len(cand)<=1: break
 if not bestcand: return False
 for fi,pl in bestcand:
  remaining[fi]-=1; chosen.append((fi,pl))
  stop=search(occ|pl['cm'],chosen)
  chosen.pop(); remaining[fi]+=1
  if stop: return True
 return False
